import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s4-u08")
C = "A2-B1"

L(1, "Como te sentes?", "Ik ben blij, verdrietig, boos, zenuwachtig…",
  ["Nomear emoções básicas"],
  vocab=[V("v-verdrietig","verdrietig","triste","adjective"), V("v-boos","boos","zangado","adjective"),
         V("v-zenuwachtig","zenuwachtig","nervoso","adjective"), V("v-bang","bang","com medo","adjective",note="Ik ben bang voor honden."),
         V("v-trots","trots","orgulhoso","adjective",note="trots op = orgulhoso de")],
  ex=[("Ik ben een beetje verdrietig.","Estou um bocadinho triste."),("Waarom ben je boos?","Porque estás zangado?"),("Ik ben zenuwachtig voor het examen.","Estou nervoso por causa do exame."),("Ik ben trots op je!","Tenho orgulho em ti!")],
  gram=[G("g-emotie-prep","Emoções + preposição","Muitas emoções pedem uma preposição fixa: **bang voor** (medo de), **trots op** (orgulho em), **boos op** (zangado com), **blij met** (contente com), **zenuwachtig voor** (nervoso por causa de).",
    [("Ze is boos op haar broer.","Ela está zangada com o irmão."),("Ik ben blij met het cadeau.","Estou contente com o presente.")],
    "As preposições raramente coincidem com as portuguesas: aprenda-as em conjunto com o adjetivo.")],
  review=["v-blij","v-moe","v-teleurgesteld"],
  cefr=C, exs=[
    MA([("verdrietig","triste"),("boos","zangado"),("zenuwachtig","nervoso"),("bang","com medo"),("trots","orgulhoso")], "Emoções.", ["v-verdrietig","v-boos","v-zenuwachtig","v-bang","v-trots"]),
    FB("Ik ben trots ___ mijn dochter.", ["op"], "trots op.", ["v-trots"], choices=["op","van","met"], tr="Tenho orgulho na minha filha."),
    FB("Mijn zoon is bang ___ het donker.", ["voor"], "bang voor.", ["v-bang"], choices=["voor","van","op"], tr="O meu filho tem medo do escuro."),
    FB("Waarom ben je boos ___ mij?", ["op"], "boos op.", ["v-boos"], choices=["op","met","tegen"], tr="Porque estás zangado comigo?"),
    TR("pt-nl","Estou nervoso por causa do exame.", ["Ik ben zenuwachtig voor het examen"], "zenuwachtig voor.", ["v-zenuwachtig"]),
    TR("nl-pt","Ik ben een beetje verdrietig.", ["Estou um [bocadinho|pouco] triste"], "verdrietig.", ["v-verdrietig"]),
    FE(["Ik","ben","blij","op","het","cadeau."], 3, "met", "blij met.", ["v-blij"]),
    LI("Ik ben zo trots op jullie!", ["Ik ben zo trots op jullie"], "Tenho tanto orgulho em vocês!", "trots op.", ["v-trots"]),
    MC("Alguém diz «Ik baal ervan». Está…", ["*aborrecido/chateado com algo","muito contente|Ao contrário.","com fome|Não."], "balen = estar chateado (coloquial).", []),
    DL([("Lieke","Je kijkt zo verdrietig. Wat is er?","Pareces tão triste. O que se passa?"),("Nuno","")], ["*Ik mis mijn familie in Portugal.","Ik ben trots.|Não combina com «triste».","Niets, ik ben boos op je.|Contraditório."], "Explicar o sentimento.", ["v-verdrietig"]),
  ], diff=3, mins=6)

L(2, "Gostar, adorar, detestar", "Ik vind het fijn / vervelend. Ik heb een hekel aan…",
  ["Exprimir gostos e aversões com intensidade"],
  vocab=[V("v-fijn","fijn","agradável|bom","adjective"), V("v-vervelend","vervelend","chato|incómodo","adjective"),
         V("v-hekel","een hekel hebben aan","detestar|não suportar","expression"), V("v-dol-op","dol zijn op","adorar","expression"),
         V("v-maakt-niet-uit","het maakt me niet uit","tanto me faz","expression")],
  ex=[("Ik vind het fijn om buiten te zijn.","Gosto de estar ao ar livre."),("Ik heb een hekel aan regen.","Detesto a chuva."),("Ze is dol op chocolade.","Ela adora chocolate."),("Het maakt me niet uit.","Tanto me faz.")],
  gram=[G("g-vinden-opiniao","Vinden + adjetivo","**Ik vind het** + adjetivo = acho (isso)…: *Ik vind het **fijn**/**vervelend**.* Com infinitivo: *Ik vind het leuk **om** te koken.* Intensidade: **dol zijn op** (adorar) > **leuk vinden** > **niet zo leuk** > **een hekel hebben aan** (detestar).",
    [("Ik vind het vervelend dat de trein vertraging heeft.","Acho chato que o comboio esteja atrasado.")])],
  review=["v-vinden","v-leuk","v-houden-van","v-mooi-vinden"],
  cefr=C, exs=[
    MA([("fijn","agradável"),("vervelend","chato"),("een hekel hebben aan","detestar"),("dol zijn op","adorar"),("het maakt me niet uit","tanto me faz")], "Gostos.", ["v-fijn","v-vervelend","v-hekel","v-dol-op","v-maakt-niet-uit"]),
    TR("pt-nl","Detesto a chuva.", ["Ik heb een hekel aan regen","Ik heb een hekel aan de regen"], "een hekel hebben aan.", ["v-hekel"]),
    TR("pt-nl","Ela adora chocolate.", ["Ze is dol op chocolade","Zij is dol op chocolade"], "dol zijn op.", ["v-dol-op"]),
    TR("nl-pt","Het maakt me niet uit.", ["Tanto me faz","É-me indiferente","Para mim tanto faz"], "Expressão fixa.", ["v-maakt-niet-uit"]),
    FB("Ik heb een hekel ___ vroeg opstaan.", ["aan"], "hekel aan.", ["v-hekel"], choices=["aan","op","van"], tr="Detesto levantar-me cedo."),
    WO("Gosto de cozinhar.", ["Ik","vind","het","leuk","om","te","koken"], "vind het leuk om te + inf.", ["v-vinden"]),
    MC("Ordene do mais positivo para o mais negativo:", ["*dol zijn op → leuk vinden → vervelend vinden → een hekel hebben aan","een hekel hebben aan → dol zijn op → leuk vinden|Ordem trocada.","vervelend → fijn → dol|Ordem trocada."], "Escala.", ["v-dol-op","v-hekel"]),
    FE(["Ik","ben","dol","aan","katten."], 3, "op", "dol op.", ["v-dol-op"]),
    LI("Ik vind het vervelend dat het zo laat is.", ["Ik vind het vervelend dat het zo laat is"], "Acho chato que seja tão tarde.", "dat + verbo no fim.", ["v-vervelend"]),
    DL([("Thomas","Wil je thee of koffie?","Queres chá ou café?"),("Leonor","")], ["*Het maakt me niet uit, wat jij neemt.","Ik heb een hekel aan thee en koffie, graag.|Contraditório.","Ik vind het.|Incompleto."], "Indiferença simpática.", ["v-maakt-niet-uit"]),
  ], diff=3, mins=6)

L(3, "Dar a opinião", "Ik vind dat… Volgens mij… Ik denk dat…",
  ["Exprimir opiniões com frases subordinadas"],
  vocab=[V("v-volgens-mij","volgens mij","na minha opinião","expression"), V("v-mening","mening","opinião","noun","de"),
         V("v-ik-denk-dat","ik denk dat","acho que","expression"), V("v-eigenlijk","eigenlijk","na verdade|afinal","adverb")],
  ex=[("Ik vind dat het te duur is.","Acho que é demasiado caro."),("Volgens mij is hij ziek.","Na minha opinião ele está doente."),("Wat is jouw mening?","Qual é a tua opinião?"),("Eigenlijk vind ik het wel leuk.","Na verdade até acho piada.")],
  gram=[G("g-opinie","Ik vind dat / volgens mij","**Ik vind dat** / **Ik denk dat** + oração com o **verbo no fim**: *Ik vind dat het te duur **is**.* **Volgens mij** no início provoca **inversão** (verbo a seguir): *Volgens mij **is** hij ziek.*",
    [("Ik denk dat het gaat regenen.","Acho que vai chover."),("Volgens mij heeft ze gelijk.","Na minha opinião ela tem razão.")],
    "Em neerlandês, «vinden» exprime opinião pessoal; «denken» é mais «suponho/acredito».")],
  review=["v-vinden","v-denken-aan","v-te"],
  cefr=C, exs=[
    MA([("volgens mij","na minha opinião"),("mening","opinião"),("ik denk dat","acho que"),("eigenlijk","na verdade")], "Opinião.", ["v-volgens-mij","v-mening","v-ik-denk-dat","v-eigenlijk"]),
    WO("Acho que é demasiado caro.", ["Ik","vind","dat","het","te","duur","is"], "Verbo no fim depois de dat.", ["v-vinden"]),
    WO("Na minha opinião ele está doente.", ["Volgens","mij","is","hij","ziek"], "Inversão depois de volgens mij.", ["v-volgens-mij"]),
    FE(["Volgens","mij","hij","heeft","gelijk."], 2, "heeft", "Depois de «Volgens mij» vem o verbo: Volgens mij heeft hij gelijk.", ["v-volgens-mij"]),
    FE(["Ik","denk","dat","het","gaat","morgen","regenen."], 4, "dat het morgen gaat regenen", "Depois de dat, os verbos vão para o fim: dat het morgen gaat regenen.", ["v-ik-denk-dat"]),
    TR("pt-nl","Qual é a tua opinião?", ["Wat is jouw mening","Wat is je mening","Wat vind jij","Wat vind je ervan"], "mening.", ["v-mening"]),
    TR("nl-pt","Eigenlijk vind ik het wel leuk.", ["Na verdade até acho piada","Na verdade até gosto","Afinal até acho giro"], "eigenlijk / wel.", ["v-eigenlijk"]),
    AR("mening","a opinião","de", "-ing → de.", ["v-mening"]),
    LI("Ik denk dat je gelijk hebt.", ["Ik denk dat je gelijk hebt","Ik denk dat jij gelijk hebt"], "Acho que tens razão.", "gelijk hebben = ter razão.", ["v-ik-denk-dat"]),
    SW("Dê a sua opinião sobre andar de bicicleta na cidade (2 frases: uma com «Ik vind dat…», outra com «Volgens mij…»).", ["Ik vind dat fietsen in de stad gezond is. Volgens mij is het ook sneller dan de auto."], ["**Ik vind dat** + verbo no fim", "**Volgens mij** + inversão", "Opinião justificada"], 12, "Duas estruturas de opinião.", ["v-volgens-mij"]),
  ], diff=4, mins=7)

L(4, "Justificar: omdat e want", "Ik ben blij, want/omdat…",
  ["Justificar sentimentos e opiniões com want e omdat"],
  vocab=[V("v-omdat","omdat","porque","conjunction",note="Verbo no fim: omdat ik moe ben."), V("v-daarom","daarom","por isso","adverb",note="Daarom ben ik blij. (inversão)"),
         V("v-reden","reden","razão|motivo","noun","de","redenen"), V("v-opgelucht","opgelucht","aliviado","adjective")],
  ex=[("Ik ben blij omdat ik geslaagd ben.","Estou contente porque passei."),("Ik ben moe, want ik heb slecht geslapen.","Estou cansado, porque dormi mal."),("Daarom ben ik zo opgelucht.","Por isso estou tão aliviado."),("Wat is de reden?","Qual é a razão?")],
  gram=[G("g-want-omdat","Want vs. omdat","Ambos = «porque». **want** liga duas orações principais → ordem normal: *…, want ik **ben** moe.* **omdat** abre uma subordinada → verbo **no fim**: *…, omdat ik moe **ben**.* **daarom** = por isso, seguido de inversão.",
    [("Ik blijf thuis, want het regent.","Fico em casa, porque está a chover."),("Ik blijf thuis omdat het regent.","Fico em casa porque está a chover.")],
    "Em português não há diferença na ordem; em neerlandês é a escolha da conjunção que decide.")],
  review=["v-want","v-blij","v-slagen"],
  cefr=C, exs=[
    MA([("omdat","porque (verbo no fim)"),("daarom","por isso"),("reden","razão"),("opgelucht","aliviado")], "Justificar.", ["v-omdat","v-daarom","v-reden","v-opgelucht"]),
    WO("Estou contente porque passei.", ["Ik","ben","blij","omdat","ik","geslaagd","ben"], "omdat → verbo no fim.", ["v-omdat"]),
    WO("Estou cansado, porque dormi mal.", ["Ik","ben","moe,","want","ik","heb","slecht","geslapen"], "want → ordem normal.", ["v-want"]),
    FE(["Ik","blijf","thuis","omdat","ik","ben","ziek."], 5, "omdat ik ziek ben", "Com omdat, o verbo vai para o fim: omdat ik ziek ben.", ["v-omdat"]),
    FB("Ik ben opgelucht, ___ het examen is goed gegaan.", ["want"], "Ordem normal → want.", ["v-want"], choices=["want","omdat","daarom"], tr="Estou aliviado, porque o exame correu bem."),
    FB("Het regent. ___ neem ik de bus.", ["Daarom"], "Por isso + inversão.", ["v-daarom"], choices=["Daarom","Omdat","Want"], tr="Está a chover. Por isso apanho o autocarro."),
    TR("pt-nl","Qual é a razão?", ["Wat is de reden"], "de reden.", ["v-reden"]),
    TR("nl-pt","Daarom ben ik zo opgelucht.", ["Por isso estou tão aliviado","É por isso que estou tão aliviado"], "daarom + inversão.", ["v-daarom","v-opgelucht"]),
    LI("Ik ben boos omdat hij te laat is.", ["Ik ben boos omdat hij te laat is"], "Estou zangado porque ele está atrasado.", "omdat.", ["v-omdat"]),
    MC("Qual está correta?", ["*Ik ga niet mee, omdat ik moe ben.","Ik ga niet mee, omdat ik ben moe.|Com omdat o verbo vai para o fim.","Ik ga niet mee, want ik moe ben.|Com want a ordem é normal."], "omdat + verbo no fim.", ["v-omdat"]),
  ], diff=4, mins=7)

L(5, "Reagir às emoções dos outros", "Wat vervelend voor je! Wat fijn! Gefeliciteerd!",
  ["Reagir com empatia a boas e más notícias"],
  vocab=[V("v-wat-vervelend","wat vervelend (voor je)","que chatice (para ti)","expression"), V("v-wat-fijn","wat fijn!","que bom!","expression"),
         V("v-sterkte","sterkte!","força! (em momentos difíceis)","expression"), V("v-balen","balen (van)","estar chateado (com)","verb",note="coloquial: Ik baal ervan.")],
  ex=[("Wat vervelend voor je!","Que chatice para ti!"),("Wat fijn dat je een baan hebt!","Que bom que arranjaste emprego!"),("Sterkte met alles.","Muita força para tudo."),("Ik baal er echt van.","Estou mesmo chateado com isso.")],
  gram=[G("g-reageren","Wat + adjetivo!","Para reagir: **Wat** + adjetivo (+ **dat** + oração): *Wat fijn!* / *Wat vervelend dat je ziek bent.* **Sterkte!** usa-se para doença, luto, exames difíceis. **Gefeliciteerd!** para boas notícias e aniversários.",
    [("Wat jammer dat je niet kunt komen.","Que pena que não possas vir.")])],
  review=["v-gefeliciteerd","v-jammer","v-beterschap"],
  cefr=C, exs=[
    MA([("wat vervelend","que chatice"),("wat fijn","que bom"),("sterkte","força"),("balen","estar chateado")], "Reagir.", ["v-wat-vervelend","v-wat-fijn","v-sterkte","v-balen"]),
    MC("Uma colega diz: «Mijn opa is overleden.»", ["*Gecondoleerd. Heel veel sterkte.","Gefeliciteerd!|Inadequado.","Wat fijn!|Inadequado."], "Luto → gecondoleerd / sterkte.", ["v-sterkte"]),
    MC("Um amigo diz: «Ik heb mijn rijbewijs gehaald!»", ["*Gefeliciteerd, wat fijn!","Sterkte!|É uma boa notícia.","Wat vervelend!|É uma boa notícia."], "Boa notícia.", ["v-wat-fijn"]),
    MC("«Mijn fiets is gestolen.»", ["*Wat vervelend voor je!","Wat fijn!|Inadequado.","Gefeliciteerd!|Inadequado."], "Má notícia.", ["v-wat-vervelend"]),
    TR("pt-nl","Que bom que arranjaste emprego!", ["Wat fijn dat je een baan hebt","Wat fijn dat je een baan hebt gevonden","Wat fijn dat je werk hebt gevonden"], "Wat fijn dat + verbo no fim.", ["v-wat-fijn"]),
    TR("nl-pt","Ik baal er echt van.", ["Estou mesmo chateado com isso","Estou mesmo aborrecido com isso"], "balen.", ["v-balen"]),
    FE(["Wat","jammer","dat","je","kunt","niet","komen."], 4, "niet kunt", "Depois de dat: dat je niet kunt komen.", ["v-jammer"]),
    LI("Heel veel sterkte morgen!", ["Heel veel sterkte morgen"], "Muita força amanhã!", "sterkte.", ["v-sterkte"]),
    DL([("Femke","Ik ben gezakt voor mijn rijexamen.","Chumbei no exame de condução."),("Pedro","")], ["*Ah, wat balen! Volgende keer lukt het vast.","Gefeliciteerd!|Ela chumbou.","Wat fijn!|Inadequado."], "Empatia + encorajamento.", ["v-balen"]),
    SW("Reaja por escrito a duas mensagens: «Ik ben ziek» e «We krijgen een baby!».", ["Wat vervelend dat je ziek bent, beterschap! / Gefeliciteerd, wat fijn!"], ["Empatia para a má notícia (**beterschap / wat vervelend**)", "Felicitação para a boa (**gefeliciteerd / wat fijn**)", "Se usou **dat**, verbo no fim"], 8, "Reações adequadas.", ["v-wat-vervelend","v-wat-fijn"]),
  ], diff=3, mins=6)

W()
